script({
  title: "The Crimson Wyrm & Dwarven Hoard",
  description: "A rearing Crimson & Gold fire dragon with articulated multi-spar bat wings, S-curved tail, open jaws breathing a sculpted plume of dragonfire, and a separate ruined dwarven treasure shrine.",
  palette: {
    scaleDark: "dark red",
    scaleBright: "red",
    belly: "tan",
    bellyDark: "dark tan",
    gold: "pearl gold",
    wing: "black",
    claw: "black",
    tooth: "white",
    stone: { mix: ["dark bluish grey", "light bluish grey", "dark bluish grey"] }
  }
});

// Helper for placing parts cleanly
const P = (part, at, colour, turn = 0) => place({ part, at, colour, turn });

// ============================================================================
// SECTION 1: TORSO AND PELVIS (Rearing S-curve core, ribbed belly, dorsal crest)
// ============================================================================
const torsoOps = [
  // --- PELVIS / HINDQUARTERS (z = -1..7, y = 8..24) ---
  // Lower belly plate & inverted slope curve (y = 8..12)
  floor({ at: [-2, 8, 1], size: [5, 5], layers: 1, colour: "bellyDark" }),
  box({ at: [-2, 9, 0], size: [5, 3, 7], colour: "belly", interior: "empty" }),
  // Forward belly step-up from pelvis toward chest (z = -2..0, y = 9..12)
  P("3665a", [-2, 9, -1], "belly", 0),
  P("3660b", [-1, 9, -1], "belly", 0),
  P("3660b", [1, 9, -1], "belly", 0),
  // Rear belly transition to tail base (z = 6..8, y = 9..12)
  P("3665a", [-2, 9, 6], "belly", 180),
  P("3660b", [-1, 9, 6], "belly", 180),
  P("3660b", [1, 9, 6], "belly", 180),

  // Mid Pelvis Core (y = 12..18, z = -1..7, x = -3..3)
  box({ at: [-3, 12, -1], size: [7, 6, 8], colour: "scaleDark", interior: "empty" }),
  // Upper Pelvis Core (y = 18..21, z = 0..6, x = -2..2)
  box({ at: [-2, 18, 0], size: [5, 3, 6], colour: "scaleDark", interior: "empty" }),
  // Pelvis lateral curved armor (y = 18..21, x = -3..-1 and x = 1..3)
  ...range(0, 6).map(z => [
    P("3040b", [-3, 18, z], z % 2 === 0 ? "scaleDark" : "scaleBright", 90),
    P("3040b", [2, 18, z], z % 2 === 0 ? "scaleDark" : "scaleBright", 270)
  ]),
  // Pelvis top rounding & dorsal ridge (y = 21..24, z = 0..6)
  ...range(0, 6).map(z => [
    P("3040b", [-2, 21, z], z % 2 === 0 ? "scaleBright" : "scaleDark", 90),
    P("3040b", [1, 21, z], z % 2 === 0 ? "scaleBright" : "scaleDark", 270),
    z % 2 === 0
      ? [P("4589", [0, 21, z], "gold"), P("54200", [0, 24, z], "bellyDark", 180)]
      : P("54200", [0, 21, z], "gold", 180)
  ]),

  // --- RISING CHEST & RIB CAGE (z = -9..0, y = 12..28) ---
  // Lower Chest (y = 12..15, z = -6..0)
  box({ at: [-3, 12, -5], size: [7, 3, 5], colour: "belly", interior: "empty" }),
  P("3665a", [-3, 12, -6], "bellyDark", 0),
  P("3660b", [-2, 12, -6], "belly", 0),
  P("3665a", [0, 12, -6], "bellyDark", 0),
  P("3660b", [1, 12, -6], "belly", 0),
  P("3665a", [3, 12, -6], "bellyDark", 0),

  // Mid Chest Core (y = 15..21, z = -8..-1, x = -4..4)
  box({ at: [-4, 15, -7], size: [9, 6, 7], colour: "scaleDark", interior: "empty" }),
  // Mid Chest Breastplate overhang (y = 15..18, z = -8..-6)
  P("3665a", [-3, 15, -8], "bellyDark", 0),
  P("3660b", [-2, 15, -8], "belly", 0),
  P("3665a", [0, 15, -8], "bellyDark", 0),
  P("3660b", [1, 15, -8], "belly", 0),
  P("3665a", [3, 15, -8], "bellyDark", 0),
  // Breastplate ribbed armor (y = 18..21, z = -9..-7)
  box({ at: [-3, 18, -8], size: [7, 3, 1], colour: "belly", interior: "solid" }),
  P("3665a", [-2, 18, -9], "bellyDark", 0),
  P("3665a", [-1, 18, -9], "belly", 0),
  P("3665a", [0, 18, -9], "gold", 0),
  P("3665a", [1, 18, -9], "belly", 0),
  P("3665a", [2, 18, -9], "bellyDark", 0),

  // Lateral Ribcage Scales (y = 15..21, x = -5 and x = 5, z = -6..-2)
  ...range(-6, -1).map(z => [
    P("3665a", [-5, 15, z], "scaleDark", 90),
    P("3665a", [4, 15, z], "scaleDark", 270),
    P("3040b", [-5, 18, z], z % 2 === 0 ? "scaleBright" : "scaleDark", 90),
    P("3040b", [4, 18, z], z % 2 === 0 ? "scaleBright" : "scaleDark", 270)
  ]),

  // Upper Chest & Broad Shoulder Girdle (y = 21..27, z = -8..0, x = -4..4)
  box({ at: [-4, 21, -7], size: [9, 6, 7], colour: "scaleDark", interior: "empty" }),
  // Upper Breastplate Slopes (y = 21..24 at z = -9..-7, and y = 24..27 at z = -8..-6)
  P("3040b", [-3, 21, -8], "scaleDark", 0),
  P("3040b", [-2, 21, -9], "bellyDark", 0),
  P("3040b", [-1, 21, -9], "belly", 0),
  P("6091", [0, 21, -9], "gold", 0),
  P("3040b", [1, 21, -9], "belly", 0),
  P("3040b", [2, 21, -9], "bellyDark", 0),
  P("3040b", [3, 21, -8], "scaleDark", 0),

  P("3040b", [-3, 24, -7], "scaleBright", 0),
  P("3040b", [-2, 24, -8], "bellyDark", 0),
  P("3040b", [-1, 24, -8], "belly", 0),
  P("54200", [0, 25, -8], "gold", 0),
  P("3040b", [1, 24, -8], "belly", 0),
  P("3040b", [2, 24, -8], "bellyDark", 0),
  P("3040b", [3, 24, -7], "scaleBright", 0),

  // Upper Back & Shoulder Slope Armor (y = 27..30, z = -4..0)
  ...range(-4, 0).map(z => [
    P("50950", [-4, 27, z], z % 2 === 0 ? "scaleDark" : "scaleBright", 90),
    P("50950", [2, 27, z], z % 2 === 0 ? "scaleDark" : "scaleBright", 270),
    P("54200", [-1, 27, z], "scaleBright", 90),
    P("54200", [1, 27, z], "scaleBright", 270),
    z % 2 === 0
      ? [P("4589", [0, 27, z], "gold"), P("54200", [0, 30, z], "bellyDark", 180)]
      : P("54200", [0, 27, z], "gold", 180)
  ])
];
section("Torso and Pelvis", torsoOps);

// ============================================================================
// SECTION 2: HIND LEGS AND FORELEGS (4 Grounded Limbs, 12 Talons, Pauldrons)
// ============================================================================
const legsOps = [
  // --- HIND LEGS (Left x = -8..-3, Right x = 3..8, z = -3..6, y = 0..18) ---
  // Left & Right Hind Foot Pads (y = 0..2, z = 0..4)
  floor({ at: [-7, 0, 0], size: [4, 4], layers: 2, colour: "scaleDark" }),
  floor({ at: [4, 0, 0], size: [4, 4], layers: 2, colour: "scaleDark" }),
  // Hind Toes & Claws (3 toes per foot: inner x=±4, middle x=±5..6, outer x=±7)
  ...[-1, 1].map(side => {
    const xs = side === -1 ? [-7, -5, -4] : [4, 5, 7];
    return xs.map((x, idx) => {
      const zOff = idx === 1 ? -3 : -2;
      return [
        P("3023b", [x, 0, zOff], "scaleDark", 90),
        P("54200", [x, 1, zOff], "claw", 0),
        P("3040b", [x, 0, zOff + 1], "scaleDark", 0),
        P("54200", [x, 3, zOff + 2], "gold", 0)
      ];
    });
  }),
  // Rear heel spurs (z = 4..5, y = 0..3)
  P("3040b", [-6, 0, 4], "claw", 180),
  P("3040b", [6, 0, 4], "claw", 180),

  // Hind Shins / Ankles (y = 2..9, z = 1..5, x = -6..-4 and 4..6)
  box({ at: [-6, 2, 1], size: [3, 6, 3], colour: "scaleDark", interior: "solid" }),
  box({ at: [4, 2, 1], size: [3, 6, 3], colour: "scaleDark", interior: "solid" }),
  // Shin front slope & rear hock spur
  P("60481a", [-6, 3, 0], "scaleBright", 0),
  P("60481a", [-5, 3, 0], "scaleDark", 0),
  P("60481a", [5, 3, 0], "scaleDark", 0),
  P("60481a", [6, 3, 0], "scaleBright", 0),
  P("3665a", [-6, 5, 4], "bellyDark", 180),
  P("3665a", [6, 5, 4], "bellyDark", 180),
  P("54200", [-6, 8, 5], "gold", 180),
  P("54200", [6, 8, 5], "gold", 180),

  // Muscular Hind Thighs (y = 8..17, z = 0..5, x = -7..-4 and 4..7)
  box({ at: [-6, 8, 0], size: [3, 6, 5], colour: "scaleDark", interior: "empty" }),
  box({ at: [4, 8, 0], size: [3, 6, 5], colour: "scaleDark", interior: "empty" }),
  // Thigh bridges into pelvis at y = 11..15
  box({ at: [-4, 9, 1], size: [1, 3, 4], colour: "scaleDark", interior: "solid" }),
  box({ at: [4, 9, 1], size: [1, 3, 4], colour: "scaleDark", interior: "solid" }),
  // Outer thigh muscle bulges (x = -7 and x = 7, y = 8..14)
  ...range(0, 5).map(z => [
    P("3665a", [-7, 8, z], "scaleDark", 90),
    P("3665a", [6, 8, z], "scaleDark", 270),
    P("3040b", [-7, 11, z], z % 2 === 0 ? "scaleBright" : "scaleDark", 90),
    P("3040b", [6, 11, z], z % 2 === 0 ? "scaleBright" : "scaleDark", 270),
    P("50950", [-6, 14, z], z % 2 === 0 ? "scaleDark" : "scaleBright", 90),
    P("50950", [4, 14, z], z % 2 === 0 ? "scaleDark" : "scaleBright", 270)
  ]),
  // Knee armor & gold spikes (z = -1..0, y = 11..16)
  P("3040b", [-5, 11, -1], "scaleBright", 0),
  P("3040b", [5, 11, -1], "scaleBright", 0),
  P("54200", [-5, 14, 0], "gold", 0),
  P("54200", [5, 14, 0], "gold", 0),

  // --- FORELEGS (Left x = -8..-4, Right x = 4..8, z = -11..-3, y = 0..23) ---
  // Crushed rock under left foreclaw (y = 0..1)
  floor({ at: [-8, 0, -11], size: [5, 4], layers: 1, colour: "stone", top: "tile" }),
  // Left & Right Forefoot Pads (y = 0..2, z = -9..-5)
  floor({ at: [-7, 0, -9], size: [4, 4], layers: 2, colour: "scaleDark" }),
  floor({ at: [4, 0, -9], size: [4, 4], layers: 2, colour: "scaleDark" }),
  // Forefoot Toes & Talons
  ...[-1, 1].map(side => {
    const xs = side === -1 ? [-7, -6, -4] : [4, 6, 7];
    return xs.map((x, idx) => {
      const zOff = idx === 1 ? -12 : -11;
      return [
        P("3023b", [x, 0, zOff], "scaleDark", 90),
        P("54200", [x, 1, zOff], "claw", 0),
        P("3040b", [x, 0, zOff + 1], "scaleDark", 0),
        P("54200", [x, 3, zOff + 2], "gold", 0)
      ];
    });
  }),

  // Forearms (y = 2..14, z = -8..-5, x = -6..-4 and 4..6)
  box({ at: [-6, 2, -8], size: [3, 12, 3], colour: "scaleDark", interior: "empty" }),
  box({ at: [4, 2, -8], size: [3, 12, 3], colour: "scaleDark", interior: "empty" }),
  // Forearm front ridges & elbow spurs
  P("60481a", [-6, 3, -9], "scaleBright", 0),
  P("60481a", [-5, 3, -9], "scaleDark", 0),
  P("60481a", [5, 3, -9], "scaleDark", 0),
  P("60481a", [6, 3, -9], "scaleBright", 0),
  P("3665a", [-5, 9, -5], "bellyDark", 180),
  P("3665a", [5, 9, -5], "bellyDark", 180),
  P("4589", [-5, 12, -4], "gold"),
  P("4589", [5, 12, -4], "gold"),
  P("54200", [-5, 15, -4], "bellyDark", 180),
  P("54200", [5, 15, -4], "bellyDark", 180),

  // Upper Arms & Shoulder Pauldrons (y = 14..23, z = -8..-3, x = -7..-4 and 4..7)
  box({ at: [-6, 14, -7], size: [2, 7, 4], colour: "scaleDark", interior: "solid" }),
  box({ at: [5, 14, -7], size: [2, 7, 4], colour: "scaleDark", interior: "solid" }),
  // Pauldron flares (x = -7 and x = 7, y = 17..23, z = -7..-3)
  ...range(-7, -3).map(z => [
    P("3665a", [-7, 17, z], "scaleDark", 90),
    P("3665a", [6, 17, z], "scaleDark", 270),
    P("50950", [-7, 20, z], z % 2 === 0 ? "scaleBright" : "scaleDark", 90),
    P("50950", [5, 20, z], z % 2 === 0 ? "scaleBright" : "scaleDark", 270)
  ]),
  // Gold Shoulder Spikes
  P("4589", [-6, 23, -6], "gold"),
  P("54200", [-6, 26, -6], "bellyDark", 90),
  P("4589", [6, 23, -6], "gold"),
  P("54200", [6, 26, -6], "bellyDark", 270)
];
section("Hind Legs and Forelegs", legsOps);

// ============================================================================
// SECTION 3: NECK, HEAD AND DRAGONFIRE
// ============================================================================
const headOps = [
  // --- ARCHED NECK (y = 27..36, z = -11..-4, x = -2..2) ---
  // Course 1 (y = 27..30, z = -8..-4)
  box({ at: [-2, 27, -7], size: [5, 3, 3], colour: "scaleDark", interior: "empty" }),
  P("3665a", [-2, 27, -8], "scaleDark", 0),
  P("3665a", [-1, 27, -8], "belly", 0),
  P("3665a", [0, 27, -8], "bellyDark", 0),
  P("3665a", [1, 27, -8], "belly", 0),
  P("3665a", [2, 27, -8], "scaleDark", 0),
  P("4589", [0, 27, -4], "gold"),
  P("54200", [0, 30, -4], "bellyDark", 180),

  // Course 2 (y = 30..33, z = -9..-5)
  box({ at: [-2, 30, -8], size: [5, 3, 3], colour: "scaleDark", interior: "empty" }),
  P("3665a", [-2, 30, -9], "scaleDark", 0),
  P("3665a", [-1, 30, -9], "belly", 0),
  P("3665a", [0, 30, -9], "bellyDark", 0),
  P("3665a", [1, 30, -9], "belly", 0),
  P("3665a", [2, 30, -9], "scaleDark", 0),
  P("3040b", [-1, 30, -5], "scaleBright", 180),
  P("4589", [0, 30, -5], "gold"),
  P("54200", [0, 33, -5], "bellyDark", 180),
  P("3040b", [1, 30, -5], "scaleBright", 180),

  // Course 3 (y = 33..36, z = -11..-6)
  box({ at: [-2, 33, -10], size: [5, 3, 4], colour: "scaleDark", interior: "empty" }),
  P("3040b", [-1, 33, -6], "scaleDark", 180),
  P("4589", [0, 33, -6], "gold"),
  P("54200", [0, 36, -6], "bellyDark", 180),
  P("3040b", [1, 33, -6], "scaleDark", 180),

  // --- OPEN LOWER JAW & FANGS (y = 32..36, z = -17..-10, x = -2..2) ---
  P("4287a", [-1, 32, -13], "belly", 0),
  P("4287a", [0, 32, -13], "bellyDark", 0),
  P("4287a", [1, 32, -13], "belly", 0),
  P("3665a", [-2, 33, -12], "scaleDark", 0),
  P("3665a", [2, 33, -12], "scaleDark", 0),
  floor({ at: [-1, 34, -17], size: [3, 4], layers: 1, colour: "scaleDark" }),
  P("85984", [-1, 33, -16], "belly", 0),
  P("54200", [1, 33, -16], "belly", 0),
  // Lower Canine Fangs & Premolars (y = 35..37)
  P("54200", [-1, 35, -17], "tooth", 180),
  P("54200", [1, 35, -17], "tooth", 180),
  P("54200", [-1, 35, -15], "tooth", 0),
  P("54200", [1, 35, -15], "tooth", 0),
  // Tongue
  P("3069b", [0, 35, -16], "scaleBright", 90),

  // --- ROARING DRAGONFIRE PLUME (y = 31..40, z = -25..-13, x = -2..2) ---
  // Multi-layered cantilevered fire core emerging from throat (z = -14)
  floor({ at: [0, 36, -19], size: [1, 7], layers: 1, colour: "yellow" }),
  floor({ at: [-1, 35, -22], size: [3, 6], layers: 1, colour: "orange" }),
  floor({ at: [-2, 34, -25], size: [5, 5], layers: 1, colour: "scaleBright" }),
  floor({ at: [-1, 33, -24], size: [3, 4], layers: 1, colour: "orange" }),
  // Sculpted upper & side fire tongues
  P("54200", [0, 37, -18], "trans yellow", 0),
  P("54200", [0, 37, -19], "trans red", 180),
  P("3040b", [-1, 36, -21], "trans yellow", 0),
  P("4589", [0, 36, -21], "trans yellow"),
  P("54200", [0, 39, -21], "trans red", 0),
  P("3040b", [1, 36, -21], "trans yellow", 0),
  P("54200", [-1, 36, -22], "orange", 90),
  P("54200", [0, 36, -22], "trans yellow", 0),
  P("54200", [1, 36, -22], "orange", 270),
  P("3040b", [-2, 35, -24], "trans red", 0),
  P("3040b", [-1, 35, -25], "orange", 0),
  P("4589", [0, 35, -24], "trans red"),
  P("54200", [0, 38, -24], "trans yellow", 0),
  P("54200", [0, 35, -25], "trans yellow", 0),
  P("3040b", [1, 35, -25], "orange", 0),
  P("3040b", [2, 35, -24], "trans red", 0),
  // Lower fire tongues
  P("3665a", [-1, 31, -23], "orange", 0),
  P("3665a", [0, 30, -24], "scaleBright", 0),
  P("3665a", [1, 31, -23], "orange", 0),

  // --- UPPER SNOUT, SKULL, EYES & HORNS (y = 36..52, z = -17..-3, x = -4..4) ---
  // Upper jaw base (y = 36..38, z = -12..-7)
  box({ at: [-2, 36, -12], size: [5, 2, 5], colour: "scaleDark", interior: "solid" }),
  // Upper palate extending forward to z = -17 at y = 37
  floor({ at: [-1, 37, -17], size: [3, 6], layers: 1, colour: "scaleDark" }),
  // Cheekbone wedge flares at y = 37 (z = -14..-10, x = -3..-2 and 2..3)
  P("41770a", [-3, 37, -14], "scaleDark", 180),
  P("41769a", [2, 37, -14], "scaleDark", 180),
  // Hanging upper fangs under palate at y = 36
  P("3024", [-1, 36, -17], "tooth"),
  P("3024", [1, 36, -17], "tooth"),
  P("3024", [-1, 36, -15], "tooth"),
  P("3024", [1, 36, -15], "tooth"),

  // Snout Bridge & Nostrils (y = 38..41, z = -17..-12)
  P("54200", [-1, 38, -17], "scaleDark", 0),
  P("54200", [0, 38, -17], "gold", 180),
  P("54200", [1, 38, -17], "scaleDark", 0),
  P("61678", [-1, 38, -16], "scaleDark", 0),
  P("50950", [0, 38, -16], "scaleBright", 0),
  P("54200", [0, 38, -13], "gold", 180),
  P("61678", [1, 38, -16], "scaleDark", 0),

  // Cranium Core & Glowing Slit Eyes (y = 38..40, z = -12..-7)
  box({ at: [-2, 38, -12], size: [5, 2, 5], colour: "scaleDark", interior: "solid" }),
  // Glowing Eyes at x = ±3, z = -12..-11, y = 38
  P("54200", [-3, 38, -12], "trans yellow", 90),
  P("54200", [3, 38, -12], "trans yellow", 270),
  P("54200", [-3, 38, -11], "orange", 90),
  P("54200", [3, 38, -11], "orange", 270),
  // Cheek Frill Spikes (x = ±3, z = -10..-9, y = 38..41)
  P("3040b", [-3, 38, -10], "gold", 180),
  P("3040b", [3, 38, -10], "gold", 180),

  // Brow Plate & Fierce Brow Ridges (y = 40..44, z = -12..-7, x = -3..3)
  floor({ at: [-3, 40, -12], size: [7, 5], layers: 1, colour: "scaleDark" }),
  P("50950", [-3, 41, -12], "scaleDark", 0),
  P("54200", [-3, 41, -9], "gold", 180),
  P("61678", [-2, 41, -12], "scaleBright", 0),
  P("3040b", [-1, 41, -12], "scaleDark", 0),
  P("50950", [0, 41, -12], "gold", 0),
  P("4589", [0, 41, -9], "gold"),
  P("54200", [0, 44, -9], "bellyDark", 180),
  P("3040b", [1, 41, -12], "scaleDark", 0),
  P("61678", [2, 41, -12], "scaleBright", 0),
  P("50950", [3, 41, -12], "scaleDark", 0),
  P("54200", [3, 41, -9], "gold", 180),

  // Twin Swept-Back Crown Horns (x = -2 and x = 2, z = -8..-5, y = 41..52)
  ...[-2, 2].map(x => [
    P("3665a", [x, 41, -8], "bellyDark", 180),
    P("3665a", [x, 44, -7], "belly", 180),
    P("54200", [x, 44, -8], "bellyDark", 0),
    P("3040b", [x, 47, -7], "belly", 0),
    P("54200", [x, 50, -6], "gold", 180)
  ]),
  // Center Crown Crest between horns (x = -1..1, z = -8..-6, y = 41..46)
  P("3040b", [-1, 41, -8], "scaleDark", 180),
  P("4589", [0, 41, -7], "gold"),
  P("54200", [0, 44, -7], "gold", 180),
  P("3040b", [1, 41, -8], "scaleDark", 180)
];
section("Neck, Head and Dragonfire", headOps);

// ============================================================================
// SECTION 4: WINGS (Articulated Multi-Spar Bat Wings, 46-Stud Wingspan)
// ============================================================================
const buildWing = (side) => {
  // side = -1 (Left, -X) or +1 (Right, +X)
  const isL = side === -1;
  const turnOut = isL ? 90 : 270;
  const turnIn = isL ? 270 : 90;
  const w2x4Rear = isL ? "41770a" : "41769a"; // tapers toward +Z when turn=180
  const w2x3Rear = isL ? "43723a" : "43722a";

  // Helper to get min X of a span [xInner..xOuter] in positive magnitude
  const spanX = (inner, width) => (isL ? -(inner + width - 1) : inner);

